  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly attributes a positive outcome, achievement, or benefit to their own actions, efforts, or advocacy, either individually or as part of a group. This includes securing funding, introducing or passing legislation, advocating for specific causes, or highlighting their role in addressing a problem or issue.",
    "clarification": "Credit-claiming is identified when the senator uses language such as 'I secured,' 'I introduced,' 'I fought for,' 'I am proud to announce,' or similar phrasing that directly ties a positive result to their personal or collective efforts. It can also include implicit claims where the senator's role is central to the described outcome, such as announcing funding they helped allocate or legislation they authored. The focus is on the senator taking ownership of a tangible or intangible benefit for their constituents, state, or the nation.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states, 'Dorgan authored legislation, which was signed into law, that created the National Center designation,' directly claiming credit for the legislative action that led to Bismarck State College's recognition."
      },
      {
        "document_id": "3482",
        "explanation": "Senator Mikulski highlights her role on the Homeland Security Appropriations Subcommittee and states, 'I will continue to fight to provide the federal support they need,' while announcing federal funding for firefighters, tying the funding directly to her advocacy."
      },
      {
        "document_id": "4585",
        "explanation": "Senator Schumer explicitly claims credit for announcing federal grants for fire departments, stating, 'Schumer was among the first senators who recognized the need for the federal government to establish a funding program,' and ties the grants to his efforts."
      }
    ],
    "negative_clarification": "Credit-claiming does NOT occur when a senator merely discusses an issue, criticizes others, or provides general commentary without explicitly or implicitly tying a positive outcome to their own actions. Statements that are purely informational, critical, or expressive of opinions—without linking those opinions to a personal or collective achievement—do not qualify as credit-claiming. Additionally, routine announcements or descriptions of legislative processes without personal attribution are not considered credit-claiming.",
    "negative_examples": [
      {
        "document_id": "50",
        "explanation": "Senator Reid criticizes the Bush Administration's position on global warming but does not attribute any positive outcome or achievement to his own actions. The statement is purely critical and does not claim credit."
      },
      {
        "document_id": "214",
        "explanation": "The text commemorates Pearl Harbor and honors military service but does not attribute any specific actions, achievements, or benefits to the senator or their efforts."
      },
      {
        "document_id": "1118",
        "explanation": "Senator Carper discusses the defeat of the gay marriage amendment and expresses his opinion but does not claim credit for any specific actions or outcomes tied to his efforts."
      }
    ]
  }
